	@Test
	void generatedNamesMatchMapAcrossCompactCapacities() {
		Random random = new Random(0x5eed);
		for (int width = 0; width <= 257; width++) {
			MapBindingSet source = new MapBindingSet(width);
			for (int i = 0; i < width; i++) {
				String name = switch (width % 3) {
				case 0 -> "column" + i;
				case 1 -> Integer.toString(random.nextInt()) + ":" + i;
				default -> "binding_" + Integer.toHexString(i);
				};
				source.addBinding(name, VF.createLiteral(i));
			}
			BindingSet copy = snapshot(source);
			assertEquals(width, copy.size());
			for (String name : source.getBindingNames()) {
				// A fresh equal String exercises hash/equality lookup rather than reference identity.
				assertSame(source.getValue(name), copy.getValue(new String(name)));
				assertTrue(copy.hasBinding(new String(name)));
				assertNull(copy.getValue(name + ":absent"));
			}
			assertEquals(source, copy);
			assertEquals(source.hashCode(), copy.hashCode());
		}
	}

	@Test
	void collisionsMissingNamesEqualityAndHashMatchMap() {
		MapBindingSet source = row("Aa", "BB", "AaAa", "BBBB", "AaBB", "BBAa");
		BindingSet copy = snapshot(source);
		assertEquals(source.size(), copy.size());
		for (Binding binding : source) {
			assertTrue(copy.hasBinding(binding.getName()));
			assertSame(binding.getValue(), copy.getValue(new String(binding.getName())));
		}
		assertFalse(copy.hasBinding("missing"));
		assertNull(copy.getValue("missing"));
		assertNull(copy.getValue(null));
		assertEquals(source.hashCode(), copy.hashCode());
		assertEquals(source, copy);
		assertEquals(copy, source);
		assertEquals(source.toString(), copy.toString());
		assertEquals(snapshot(new MapBindingSet()), new MapBindingSet());
	}

	@Test
	void returnedBindingsRemainStableAndMutableViewsStayLive() {
		MapBindingSet copy = (MapBindingSet) snapshot(row("a", "b", "c"));
		Binding retained = copy.getBinding("a");
		assertSame(retained, copy.getBinding("a"));
		Set<String> names = copy.getBindingNames();
		assertTrue(names.remove("b"));
		assertFalse(copy.hasBinding("b"));
		copy.setBinding("a", VF.createIRI("urn:replacement"));
		assertEquals("urn:a", retained.getValue().stringValue());
		copy.addBinding("d", VF.createIRI("urn:d"));
		assertEquals(List.of("a", "c", "d"), new ArrayList<>(names));
		Iterator<Binding> it = copy.iterator();
		assertEquals("a", it.next().getName());
		it.remove();
		assertFalse(copy.hasBinding("a"));
		assertThrows(IllegalStateException.class, it::remove);
		names.clear();
		assertEquals(0, copy.size());
	}

